R=[
("अंडा और सब्ज़ी कैसरोल",
"यह मेहमानों को परोसने के लिए एक बढ़िया व्यंजन है। यह मुख्य व्यंजन के रूप में 8 लोगों के लिए है, या इसे छोटे टुकड़ों में काटकर स्टार्टर के रूप में परोसें तो और भी लोगों के लिए। आप इसे मफ़िन पैन में भी बेक कर सकते हैं, जिससे नाश्ते के लिए सही मात्रा वाले, साथ ले जाने योग्य टुकड़े बन जाते हैं।",
"8","1 टुकड़ा",
["1 स्प्रे, 0.25 ग्राम नॉनस्टिक कुकिंग स्प्रे","2 बड़े चम्मच ऑलिव ऑयल","1 छोटा प्याज़ (बारीक कटा हुआ)","2 कली लहसुन (बारीक कटा हुआ)","1 मध्यम तोरी/ज़ुकीनी (बहुत पतली कटी हुई)","4 बड़े टमाटर (पके हुए, बीज निकाले और कटे हुए)","1 कप पालक की पत्तियाँ (कटी हुई)","1/2 कप ताज़ा तुलसी (कटी हुई)","1/2 कप ताज़ा अजमोद/पार्स्ली (कटा हुआ)","1 टहनी ताज़ा रोज़मेरी (कटी हुई)","12 बड़े अंडों की सफ़ेदी","4 औंस ताज़ा मोज़रेला (क्यूब्स में कटा हुआ)","1 चुटकी ताज़ी पिसी काली मिर्च, स्वादानुसार","1 चुटकी कोशर नमक"],
["ओवन को 350°F पर पहले से गरम करें।","एक बड़े कैसरोल डिश में नॉनस्टिक कुकिंग स्प्रे लगाएँ।","भारी तले की फ्राइंग पैन में ऑलिव ऑयल गरम करें और लहसुन व प्याज़ डालें। प्याज़ के नरम होने तक लगातार चलाते हुए पकाएँ।","तोरी डालें और 1–2 मिनट और भूनें।","कटे हुए टमाटर और पालक की पत्तियाँ डालकर 2 मिनट पकाएँ, फिर तुलसी, अजमोद और रोज़मेरी डालें। जड़ी-बूटियों और पालक के मुरझाने तक पकाते रहें।","एक कटोरे में अंडों की सफ़ेदी, पकी हुई सब्ज़ियाँ और चीज़ मिलाएँ। चाहें तो नमक और काली मिर्च डालें।","मिश्रण को कैसरोल में डालें और 40–45 मिनट तक, या फ्रिटाटा के जमने तक बेक करें। ठंडा होने दें, फिर 8 बराबर टुकड़ों में काटें।"],[]),
("पेस्टो चिकन",
"यह पेस्टो चिकन रेसिपी ज़ुकीनी नूडल्स के साथ बहुत अच्छी लगती है और कम कार्बोहाइड्रेट वाला, इतालवी अंदाज़ का भोजन बनाती है।",
"4","1 चिकन ब्रेस्ट",
["1 छोटा चम्मच ऑलिव ऑयल","1 1/4 पाउंड बिना हड्डी और बिना त्वचा के चिकन ब्रेस्ट (पतले आधे-आधे कटे हुए)","1/4 कप पेस्टो सॉस","1 बड़ा चम्मच ताज़ी तुलसी (कटी हुई, सजाने के लिए, वैकल्पिक)"],
["अपने ग्रिल या ग्रिल पैन को मध्यम-तेज़ आँच पर पहले से गरम करें। उस पर ऑलिव ऑयल लगाएँ।","चिकन ब्रेस्ट को एक उथले बर्तन में रखें और उन पर पेस्टो सॉस बराबर से लगा दें।","मैरिनेट किए हुए चिकन ब्रेस्ट को हर तरफ़ लगभग 6–8 मिनट तक, या पूरी तरह पकने तक ग्रिल करें; अंदर का तापमान 165 डिग्री F होना चाहिए।","चिकन को ग्रिल से उतारें और परोसने से पहले कुछ मिनट रखा रहने दें।"],[]),
("भुनी हुई मेपल डिजॉन गाजर",
"इस मधुमेह के अनुकूल साइड डिश में गाजर की प्राकृतिक मिठास, डिजॉन सरसों का तीखा स्वाद और मेपल सिरप की गहरी गर्माहट एक साथ मिलती है।",
"4","1/2 कप",
["1 पाउंड गाजर (छिली हुई और स्टिक्स में कटी हुई)","2 बड़े चम्मच ऑलिव ऑयल","5 छोटे चम्मच मेपल सिरप","1 बड़ा चम्मच डिजॉन सरसों","1 कली लहसुन (बारीक कटी हुई)","1 छोटा चम्मच सूखा थाइम","1/4 छोटा चम्मच नमक","1/2 छोटा चम्मच काली मिर्च"],
["ओवन को 400 डिग्री F पर पहले से गरम करें। बेकिंग शीट पर चर्मपत्र कागज़ बिछाएँ।","एक कटोरे में ऑलिव ऑयल, मेपल सिरप, डिजॉन सरसों, कटा लहसुन, सूखा थाइम, नमक और काली मिर्च को फेंटकर मिलाएँ।","गाजर की स्टिक्स को कटोरे में डालें और मैरिनेड से बराबर लिपटने तक मिलाएँ। गाजर को कम से कम 30 मिनट मैरिनेट होने दें।","मैरिनेट की हुई गाजर की स्टिक्स को तैयार बेकिंग शीट पर एक परत में फैलाएँ।","पहले से गरम ओवन में 25 मिनट तक, या गाजर के नरम और हल्के कैरेमलाइज़ होने तक भूनें; बीच में एक बार चलाएँ।"],[]),
("नींबू के साथ काली बीन्स और टमाटर",
"नींबू के साथ काली बीन्स और टमाटर की यह रेसिपी चटपटे और खट्टे-मीठे स्वाद वाली है। काली बीन्स और टमाटर इसे भरपूर और हल्का मीठा आधार देते हैं, जबकि जीरा गर्म, मिट्टी जैसा मसालेदार स्वाद जोड़ता है। नींबू का रस ताज़ा और तीखा खट्टापन देता है, और प्याज़ व शिमला मिर्च हल्की मिठास और थोड़ा कुरकुरापन देते हैं।",
"4","2/3 कप",
["2 बड़े चम्मच एक्स्ट्रा वर्जिन ऑलिव ऑयल (बाँटकर उपयोग करें)","1/2 कप प्याज़ (बारीक कटा हुआ)","1/2 कप हरी शिमला मिर्च या पोब्लानो मिर्च (बारीक कटी हुई)","1 (15 औंस) कैन काली बीन्स (बिना नमक मिलाए, धोकर छानी हुई)","1 कप ग्रेप टमाटर (चार टुकड़ों में कटे हुए)","1/2 छोटा चम्मच पिसा जीरा","1/4 छोटा चम्मच नमक","1 बड़ा चम्मच नींबू का रस"],
["एक मध्यम कड़ाही में मध्यम-तेज़ आँच पर 1 छोटा चम्मच तेल गरम करें। प्याज़ और शिमला मिर्च डालें और बीच-बीच में चलाते हुए 3 मिनट तक, या प्याज़ के हल्का भूरा होना शुरू होने तक पकाएँ।","बीन्स, टमाटर और जीरा डालें। बीच-बीच में चलाते हुए 3 मिनट तक, या टमाटर के बस नरम होने तक पकाएँ। आँच से उतार लें।","ऊपर से नमक छिड़कें और नींबू का रस तथा बचा हुआ तेल सब पर बराबर डालें। चलाएँ नहीं।"],[]),
("मीठा-खट्टा बेक्ड चिकन",
"इस व्यंजन में मीठे और खट्टे स्वादों का सुखद संतुलन है, और चिकन को बेक करना तलने का हल्का विकल्प है। यह परिवार को पसंद आने वाला भोजन है जो खाने की मेज़ पर ज़रूर पसंद किया जाएगा।",
"4","1 चिकन थाई + 1/2 कप शिमला मिर्च का मिश्रण",
["4 बिना हड्डी और बिना त्वचा की चिकन थाई (हर एक लगभग 4 औंस)","1/4 छोटा चम्मच काली मिर्च","3/4 कप अनानास का रस","3 बड़े चम्मच केचप","1 बड़ा चम्मच कम सोडियम वाली सोया सॉस","1 1/2 बड़े चम्मच राइस विनेगर","1 1/2 बड़े चम्मच ब्राउन शुगर का विकल्प","1 बड़ा चम्मच कॉर्नस्टार्च","1 बड़ा चम्मच कैनोला ऑयल","1 मध्यम लाल शिमला मिर्च (पतली कटी हुई)","1 मध्यम हरी शिमला मिर्च (पतली कटी हुई)","1 कप अनानास (छोटे टुकड़ों में कटा हुआ)","2 डंठल हरा प्याज़ (स्प्रिंग ओनियन) (कटा हुआ, सजाने के लिए)","2 छोटे चम्मच तिल (भुने हुए)"],
["ओवन को 375 डिग्री F पर पहले से गरम करें। चिकन थाई पर काली मिर्च लगाएँ।","एक छोटे कटोरे में अनानास का रस, केचप, सोया सॉस, राइस विनेगर, ब्राउन शुगर और कॉर्नस्टार्च को अच्छी तरह मिलने तक फेंटें। एक तरफ़ रख दें।","ओवन में रखने योग्य कड़ाही या बेकिंग डिश में मध्यम-तेज़ आँच पर कैनोला ऑयल गरम करें। चिकन थाई डालें और हर तरफ़ लगभग 3–4 मिनट तक सुनहरा भूरा होने तक सेकें।","तैयार किया हुआ मीठा-खट्टा सॉस चिकन पर डालें, ध्यान रखें कि हर टुकड़ा अच्छी तरह ढक जाए।","कड़ाही में चिकन के चारों ओर कटी हुई लाल और हरी शिमला मिर्च तथा अनानास के टुकड़े बिखेर दें।","कड़ाही को पहले से गरम ओवन में रखें और लगभग 25 मिनट तक बेक करें, या जब तक चिकन के अंदर का तापमान 165 डिग्री F न हो जाए और सॉस बुलबुले के साथ गाढ़ा न हो जाए।","ओवन से निकालें और कुछ मिनट रखा रहने दें।","कटे हुए हरे प्याज़ और भुने हुए तिल से सजाएँ।"],[]),
("शाकाहारी मसूर पुलाव (दाल पुलाव)",
"और अधिक शाकाहारी या वीगन रेसिपी विकल्प ढूँढ रहे हैं? पाकिस्तान का यह स्वादिष्ट पारंपरिक व्यंजन आज़माएँ। इसमें लाल मसूर दुबले प्रोटीन का स्रोत हैं और तरह-तरह के मसाले सोडियम को बहुत कम रखते हुए स्वाद बढ़ाते हैं। भाप में पकी हरी बीन्स के साथ इस भोजन को पूरा करें।",
"5","3/4 कप पुलाव + 1/2 कप हरी बीन्स",
["1 कप ब्राउन बासमती चावल (धोया हुआ)","1/2 कप लाल मसूर (धोई हुई)","1 मध्यम पीला प्याज़ (पतला कटा हुआ)","2 छोटे चम्मच ऑलिव ऑयल","1/2 छोटा चम्मच जीरा","1 तेज पत्ता","2 लौंग","1/2 छोटा चम्मच हल्दी","1/4 छोटा चम्मच लाल मिर्च पाउडर","2 कप कम सोडियम वाला सब्ज़ी का शोरबा","1/2 कप हरा धनिया (कटा हुआ)","2 कप ताज़ी या जमी हुई हरी बीन्स (भाप में पकी हुई)"],
["एक बर्तन में ऑलिव ऑयल गरम करें। प्याज़ को सुनहरा भूरा होने तक भूनें।","जीरा, तेज पत्ता, लौंग, हल्दी और लाल मिर्च पाउडर डालें। 1 मिनट चलाएँ। चावल और मसूर डालें और मसालों में लपेटने के लिए चलाएँ।","सब्ज़ी का शोरबा डालें, ढक दें और चावल व मसूर के पकने तक 25–30 मिनट धीमी आँच पर पकाएँ।","हरे धनिये से सजाएँ।","1/2 कप भाप में पकी हरी बीन्स के साथ परोसें।","वैकल्पिक चरण: हम इसे खीरे के रायते के साथ परोसने की सलाह देते हैं, जो इस रेसिपी के पोषण विश्लेषण में शामिल नहीं है।"],[]),
("दो-बीन स्ट्यू",
"दो-बीन स्ट्यू काबुली चने और कैनेलिनी बीन्स का स्वादिष्ट मेल है, जिसमें प्याज़, अजवाइन के डंठल (सेलेरी), गाजर और लीक जैसी सब्ज़ियों का मिश्रण है। इस स्ट्यू में लहसुन, सफ़ेद वाइन और कटे टमाटर का मसाला है, जो इसे भरपूर, सुगंधित स्वाद देता है, जबकि ताज़ा ओरेगानो जड़ी-बूटी की ताज़गी जोड़ता है। नींबू के रस और छिलके का हल्का स्वाद ताज़ा खट्टापन देता है, जो नमकीन स्वाद को बख़ूबी संतुलित करता है।\n\nयह स्ट्यू स्वाद के लिए ही नहीं, बल्कि पौष्टिक विकल्प के रूप में भी बढ़िया है, क्योंकि इसमें फ़ाइबर और प्रोटीन भरपूर है। यह बहुमुखी व्यंजन भूमध्यसागरीय और इतालवी पाक परंपराओं में अच्छी तरह फिट बैठता है, जो इसे पौष्टिक दोपहर या रात के भोजन के लिए शानदार विकल्प बनाता है।",
"8","1 कप",
["1 बड़ा चम्मच ऑलिव ऑयल","1 मध्यम प्याज़ (कटा हुआ)","2 डंठल अजवाइन के डंठल/सेलेरी (कटे हुए)","1 मध्यम गाजर (छिली और बारीक कटी हुई)","1 डंठल लीक (केवल सफ़ेद भाग, साफ़ किया और कटा हुआ)","3 कली लहसुन (बारीक कटी हुई)","2 (14.5 औंस) कैन कटे हुए टमाटर","2 छोटे चम्मच नींबू का छिलका (ज़ेस्ट)","1 1/2 कप चिकन या सब्ज़ी का शोरबा (कम सोडियम वाला)","1 (15 औंस) कैन कैनेलिनी बीन्स (बिना नमक मिलाए, छानकर धोई हुई)","1 (15 औंस) कैन काबुली चने (छोले) (बिना नमक मिलाए, छानकर धोए हुए)","1 कप केल (डंठल निकाले हुए, कटे हुए)","2 बड़े चम्मच नींबू का रस","1/3 कप ताज़ा ओरेगानो","1/2 छोटा चम्मच कोशर नमक"],
["एक बड़े सॉसपैन में मध्यम आँच पर तेल गरम करें। प्याज़ और सेलेरी डालकर 4 मिनट भूनें। गाजर और लीक डालें और सब्ज़ियों के नरम होने तक 6 से 7 मिनट भूनें। लहसुन डालें और 1 मिनट भूनें।","टमाटर और नींबू का छिलका डालें और 1 मिनट पकाएँ। शोरबा डालें और उबाल आने दें। आँच कम करें, ढक दें और मिश्रण के गाढ़ा होने तक 20 मिनट धीमी आँच पर पकाएँ।","बीन्स और कटी हुई केल डालें और बिना ढके 5 मिनट पकाएँ। नींबू का रस, ओरेगानो, नमक और काली मिर्च मिलाएँ और 1 मिनट और पकाएँ।"],[]),
("ब्राउन राइस पर सब्ज़ियों के साथ स्लो कुकर बटर चिकन",
"ब्राउन राइस पर सब्ज़ियों के साथ स्लो कुकर बटर चिकन एक आरामदायक और सुगंधित व्यंजन है। नरम चिकन को गाढ़े, मलाईदार टमाटर सॉस, मिली-जुली सब्ज़ियों और गर्म मसालों के साथ धीमी आँच पर पकाया जाता है, फिर पौष्टिक ब्राउन राइस पर परोसा जाता है। यह स्वाद और बनावट का बेहतरीन मेल है, जो भूमध्यसागरीय शैली और कम वसा वाले आहार पैटर्न के आरामदायक रात के भोजन के लिए आदर्श है।",
"4","1 1/2 कप चिकन, 1/2 कप चावल",
["1 छोटा चम्मच ऑलिव ऑयल","1 मध्यम प्याज़ (बारीक कटा हुआ)","2 कली लहसुन (बारीक कटी हुई)","1 बड़ा चम्मच ताज़ा अदरक (कद्दूकस किया हुआ)","2 छोटे चम्मच गरम मसाला","1 छोटा चम्मच जीरा","1 छोटा चम्मच पिसा धनिया","1/2 छोटा चम्मच हल्दी","1/4 छोटा चम्मच लाल मिर्च (कायेन पेपर)","1 पाउंड बिना हड्डी और बिना त्वचा के चिकन ब्रेस्ट (निवाले के आकार के टुकड़ों में कटे हुए)","2 मध्यम गाजर (मध्यम टुकड़ों में कटी हुई)","1 मध्यम तोरी/ज़ुकीनी (मध्यम टुकड़ों में कटी हुई)","1 कप बिना नमक मिलाए कुचले हुए टमाटर (कैन वाले या ताज़े)","1/2 कप लाइट नारियल का दूध","1/2 छोटा चम्मच नमक","1/2 कप सादा बिना वसा वाला ग्रीक योगर्ट","2 कप पका हुआ ब्राउन राइस","2 बड़े चम्मच ताज़ा हरा धनिया (कटा हुआ)"],
["एक बड़ी कड़ाही में मध्यम आँच पर ऑलिव ऑयल गरम करें। प्याज़ डालें और नरम होने तक 3–4 मिनट भूनें। लहसुन, अदरक, गरम मसाला, जीरा, धनिया, हल्दी और लाल मिर्च डालें। खुशबू आने तक 1 मिनट पकाएँ।","प्याज़ के मिश्रण को स्लो कुकर में डालें। चिकन, गाजर, तोरी, कुचले हुए टमाटर, नारियल का दूध और नमक डालें। मिलाने के लिए चलाएँ।","ढक दें और चिकन के नरम और पूरी तरह पकने तक धीमी आँच पर 6–8 घंटे या तेज़ आँच पर 3–4 घंटे पकाएँ।","चिकन पक जाने पर, मलाईदार सॉस बनाने के लिए ग्रीक योगर्ट मिलाएँ।","पके हुए ब्राउन राइस को 4 कटोरों या प्लेटों में बाँट दें। चावल पर बटर चिकन और सब्ज़ियाँ डालें। ताज़े हरे धनिये से सजाएँ।"],[]),
("रोज़मेरी और लहसुन के साथ भुने चेरी टमाटर",
"टोस्ट पर परोसे जाने वाले रोज़मेरी और लहसुन के साथ भुने चेरी टमाटर एक सरल और स्वादिष्ट व्यंजन हैं, जो मधुमेह के अनुकूल बढ़िया स्टार्टर बनाते हैं। यह एक आसान रेसिपी है जिसमें भुने टमाटरों के चमकीले रंग और स्वाद के साथ ताज़ी रोज़मेरी और सुगंधित लहसुन का मेल है।",
"8","1/4 कप टमाटर और टोस्ट के 3 चौथाई टुकड़े",
["24 औंस चेरी टमाटर","1 बड़ा चम्मच ताज़ी रोज़मेरी (कटी हुई)","1/2 छोटा चम्मच नमक","1 कली लहसुन (छिलका उतारा हुआ और ऊपर से कटा हुआ)","1/2 कप ऑलिव ऑयल","6 स्लाइस साबुत गेहूँ की ब्रेड (टोस्ट की हुई और चार टुकड़ों में कटी हुई)"],
["ओवन को 400 डिग्री F पर पहले से गरम करें।","टमाटर, रोज़मेरी, नमक और लहसुन को एक गोल बेकिंग डिश में रखें।","तेल डालें और मिलाने के लिए चलाएँ। ओवन में रखें और 45–60 मिनट तक, लहसुन के सुनहरा भूरा और नरम होने तथा टमाटरों के फटने तक पकाएँ।","लहसुन की कलियों को गाँठ से निचोड़कर निकालें और टमाटरों में मिला दें। लहसुन की कलियाँ नरम और मलाईदार होंगी।","टोस्ट के हर चौथाई टुकड़े पर टमाटर का मिश्रण डालें। एक सर्विंग यानी टोस्ट के 3 चौथाई स्लाइस के साथ 1/4 कप टमाटर।"],[]),
("सब्ज़ियों वाला प्रोवेंसल टार्ट",
"रॉबिन वेब की एक सहेली फ़्रांस के आर्ल्स में कुकिंग स्कूल चलाती हैं, और रॉबिन जब भी वहाँ जाती हैं, उनकी सहेली उनके लिए अपना शानदार सब्ज़ी टार्ट बनाती हैं। उनके टार्ट में वसा थोड़ी ज़्यादा होती है, लेकिन रॉबिन ने इसे कुछ कम कर दिया। पूरा स्वाद, पर पूरी वसा नहीं।",
"8","1/8 टार्ट",
["1 स्प्रे, 0.25 ग्राम नॉनस्टिक कुकिंग स्प्रे","1 बड़ा मीठा प्याज़ (विडालिया या कोई अन्य मीठा प्याज़, आधा करके 1/3 इंच के टुकड़ों में कटा हुआ)","1 छोटा चम्मच बालसमिक सिरका (अच्छी गुणवत्ता का)","1 1/2 कप मैदा (ऑल-पर्पज़ आटा)","1 1/2 छोटे चम्मच ताज़ा थाइम (कटा हुआ)","1/2 छोटा चम्मच कोशर नमक (बाँटकर उपयोग करें)","1/3 कप बर्फ़ का ठंडा पानी","2 बड़े चम्मच ऑलिव ऑयल","1 बड़ा चम्मच डिजॉन सरसों","1 मध्यम तोरी/ज़ुकीनी (तिरछी काटकर 1/8 इंच लंबे स्लाइस में)","1/2 छोटा चम्मच काली मिर्च (बाँटकर उपयोग करें)","2 मध्यम टमाटर (1/4 इंच के स्लाइस में कटे हुए)","2 बड़े चम्मच परमेसन चीज़ (ताज़ा कद्दूकस किया हुआ)","1/4 कप ताज़ी तुलसी (कटी हुई)"],
["एक बड़ी नॉनस्टिक कड़ाही में नॉनस्टिक कुकिंग स्प्रे लगाएँ और गरम होने तक मध्यम-तेज़ आँच पर रखें। आँच को मध्यम-धीमी करें और प्याज़ को बहुत नरम और सुनहरा होने तक, लगभग 20 मिनट भूनें। बालसमिक सिरका डालें और 5 मिनट और भूनें। प्लेट में निकाल लें।","ओवन को 400°F पर पहले से गरम करें। एक बड़े कटोरे में मैदा, थाइम और 1/4 छोटा चम्मच नमक मिलाएँ। पानी और तेल डालकर बस इतना चलाएँ कि नरम आटा बन जाए। काम की सतह पर हल्का आटा छिड़कें और बेलन से आटे को 16 × 10 इंच के आयत या 13 इंच के गोले में बेलें। इसे आधा मोड़ें और निकाले जा सकने वाली तली वाले 12 × 6 इंच के टार्ट पैन या 9 इंच के गोल टार्ट पैन में डालें। किनारों को काट लें। चम्मच के पिछले हिस्से से टार्ट की तली पर डिजॉन सरसों बराबर फैलाएँ।","कड़ाही में फिर से हल्का नॉनस्टिक कुकिंग स्प्रे लगाएँ और मध्यम आँच पर रखें। कड़ाही में तोरी और 1/4 छोटा चम्मच काली मिर्च डालें और सुनहरा होने तक 5–7 मिनट भूनें।","टार्ट की तली पर टमाटर की एक परत लगाएँ, उसके ऊपर तोरी, फिर बचे हुए टमाटरों की एक और परत और प्याज़, इन्हें हल्का-सा एक-दूसरे पर चढ़ाते हुए लगाएँ। बचा हुआ 1/4 छोटा चम्मच नमक, 1/4 छोटा चम्मच काली मिर्च और परमेसन चीज़ छिड़कें। लगभग 20 मिनट तक, टार्ट के हल्का सुनहरा भूरा होने तक बेक करें। ओवन से निकालकर ऊपर से तुलसी छिड़कें और 3 मिनट के लिए वापस ओवन में रखें। टार्ट को 5 मिनट ठंडा होने दें, फिर तिकोने टुकड़ों में काटकर परोसें।"],[]),
("सेहतमंद घर पर बना ग्रीन बीन कैसरोल",
"थैंक्सगिविंग का यह पारंपरिक साइड डिश अपना भरपूर, नमकीन स्वाद खोए बिना मधुमेह के अनुकूल रूप में बदल जाता है।",
"7","1/2 कप",
["1 नॉनस्टिक कुकिंग स्प्रे","4 लाइट क्रीमी स्विस चीज़ वेज","1 बड़ा चम्मच कैनोला ऑयल","1/2 प्याज़ (बारीक कटा हुआ)","1 छोटा चम्मच मार्जरीन","8 औंस सफ़ेद (बटन) मशरूम (कटे हुए)","1/8 छोटा चम्मच नमक","1/4 छोटा चम्मच काली मिर्च","1/2 कप कम सोडियम वाला सब्ज़ी का शोरबा","2 छोटे चम्मच कॉर्नस्टार्च","2 छोटे चम्मच ठंडा पानी","1/4 कप 1% दूध","2 (14.5 औंस) कैन बिना नमक मिलाए कटी हुई डिब्बाबंद हरी बीन्स (छानी हुई)","1 कप कॉर्न फ्लेक्स (कुचले हुए)","1 2/3 बड़े चम्मच मार्जरीन (पिघला हुआ)"],
["ओवन को 400 डिग्री पर पहले से गरम करें। 1.5 क्वार्ट की बेकिंग डिश पर कुकिंग स्प्रे लगाएँ।","चीज़ वेज को माइक्रोवेव में 30 सेकंड गरम करें, फिर चलाएँ। एक तरफ़ रख दें।","एक बड़ी सॉते पैन में मध्यम आँच पर तेल गरम करें। प्याज़ डालें और 2-3 मिनट भूनें।","पैन में मार्जरीन डालकर पिघलने दें। मशरूम, नमक और काली मिर्च डालें और 4-5 मिनट पकाएँ। पैन में शोरबा डालें और 1 मिनट धीमी आँच पर पकाएँ।","एक छोटे कटोरे में कॉर्नस्टार्च और पानी मिलाएँ; इसे शोरबे में डालें और 1 मिनट चलाएँ।","पैन में पिघली हुई चीज़ डालें और अच्छी तरह मिलाएँ। पैन में दूध डालें; मिलाने के लिए चलाएँ। गाढ़ा होने तक 2-3 मिनट और पकाएँ।","आँच से उतारें और हरी बीन्स मिलाएँ। हरी बीन्स के मिश्रण को बेकिंग डिश में डालें।","एक छोटे कटोरे में कॉर्न फ्लेक्स और मार्जरीन मिलाकर कॉर्न फ्लेक्स की टॉपिंग तैयार करें। कॉर्न फ्लेक्स का मिश्रण हरी बीन्स के ऊपर फैलाएँ। 15-20 मिनट बेक करें।"],[]),
("एवोकाडो, टमाटर और प्याज़ के सलाद के साथ बेक्ड अंडा",
"यह प्रोटीन से भरपूर, झटपट बनने वाला नाश्ता है, जिसमें दक्षिण-पश्चिमी शैली के नमकीन स्वाद हैं।",
"2","1 अंडा और 1/2 कप सलाद",
["2 बड़े अंडे","1 स्प्रे, 0.25 ग्राम नॉनस्टिक कुकिंग स्प्रे","1 छोटा चम्मच कैनोला ऑयल","2 बड़े चम्मच नींबू का रस","1/4 छोटा चम्मच कोशर नमक","1/2 छोटा चम्मच काली मिर्च (दरदरी पिसी)","1/4 साबुत हैस एवोकाडो (क्यूब्स में कटा हुआ)","1 बड़ा टमाटर (पतला कटा हुआ)","1/4 कप लाल प्याज़ (छिला और पतला कटा हुआ)","1/4 कप हरा धनिया (बारीक कटा हुआ)"],
["ओवन को 400°F पर पहले से गरम करें।","हर अंडे को अलग कटोरे में तोड़ें और जर्दी न फूटने दें। एक तरफ़ रख दें।","एक छोटी ओवन-सुरक्षित नॉनस्टिक पैन पर कुकिंग स्प्रे लगाकर उसे पहले से गरम करें। अंडे डालें और तुरंत पैन को ओवन में रख दें। लगभग 2–5 मिनट तक, या अंडों के मनचाहे पकने तक पकाएँ।","एक छोटे कटोरे में कैनोला ऑयल, नींबू का रस, नमक और काली मिर्च डालकर फेंटें और ड्रेसिंग बनाएँ। ड्रेसिंग में एवोकाडो, टमाटर, लाल प्याज़ और हरा धनिया डालकर मिलाएँ।","अंडों को ओवन से निकालें। पहले सलाद की सामग्री प्लेट में रखें और उसके ऊपर अंडे रखें। परोसें।"],[]),
("काली बीन्स और आम की सालसा वाले लेट्यूस रैप",
"टॉर्टिला रैप के विकल्प के रूप में कम कार्बोहाइड्रेट वाले बटर लेट्यूस का उपयोग करें। अगर आपको मसालेदार खाना पसंद नहीं है, तो जलापेनो की जगह कटी हुई हरी शिमला मिर्च डालें।",
"5","2 लेट्यूस कप",
["1 (15 औंस) कैन काली बीन्स (धोकर छानी हुई)","1 आम (छिला हुआ, क्यूब्स में कटा हुआ, और कठोर गुठली के पास का हिस्सा निचोड़कर 1 बड़ा चम्मच रस निकाला हुआ)","1/2 छोटा लाल प्याज़ (बारीक कटा हुआ)","1 मध्यम जलापेनो मिर्च (बीज निकाले और बारीक कटी हुई)","1 बड़ी लाल शिमला मिर्च (बीज निकाले और बारीक कटी हुई)","2 बड़े चम्मच रेड वाइन विनेगर","1 बड़ा चम्मच ऑलिव ऑयल","1 बड़ा चम्मच शहद या 2 पैकेट कृत्रिम मीठा","10 बटर लेट्यूस (बटर लेट्यूस की पत्तियाँ)"],
["लेट्यूस को छोड़कर सभी सामग्री को एक मध्यम आकार के कटोरे में मिलाएँ। मैरिनेट होने के लिए कम से कम एक घंटे, या दो दिन तक फ्रिज में रखें (जितना ज़्यादा समय, उतना बेहतर)।","अगर बटर लेट्यूस की पत्तियों का उपयोग कर रहे हैं, तो उन्हें एक बड़ी प्लेट में सजाएँ और हर एक में 1/4 कप सलाद का मिश्रण भरें।","परोसने का वैकल्पिक सुझाव: परोसने के लिए लेट्यूस की जगह जिकामा का उपयोग करें। जिकामा को छीलें और 1/4 इंच मोटे गोल टुकड़ों में काटें, फिर इन गोलों को टॉर्टिला चिप्स जैसा दिखाने के लिए तिकोने टुकड़ों (आठ भाग) में काटें। टॉर्टिला चिप्स की जगह कच्चे जिकामा \"चिप्स\" का उपयोग करके चिप्स और सालसा की तरह परोसें।"],[]),
("कद्दू का हमस",
"पारंपरिक हमस में पतझड़ का स्वाद जोड़ें! इस स्वादिष्ट हमस को ताज़ी सब्ज़ियों या पीटा चिप्स के साथ परोसें, या झटपट नाश्ते के लिए इसे टोस्ट पर खाएँ।",
"7","1/4 कप",
["1 (15 औंस) कैन काबुली चने (छोले) (छानकर धोए हुए)","1/2 कप डिब्बाबंद कद्दू","2 बड़े चम्मच ताहिनी","1 बड़ा चम्मच ऑलिव ऑयल","1 बड़ा चम्मच नींबू का रस","2 कली लहसुन","1/4 छोटा चम्मच स्मोक्ड पेपरिका","स्वादानुसार ताज़ी पिसी काली मिर्च","1 छोटा चम्मच कद्दू के बीज (वैकल्पिक)"],
["कद्दू के बीजों को छोड़कर सभी सामग्री को फ़ूड प्रोसेसर या ब्लेंडर में डालें और चिकना होने तक पीसें।","चाहें तो ऊपर से कद्दू के बीज छिड़ककर सजाएँ। पीटा चिप्स या सेलेरी, शुगर स्नैप पीज़ या गाजर जैसी ताज़ी सब्ज़ियों के साथ परोसें।"],[]),
("सैल्मन क्विनोआ रिसोट्टो",
"लेखिका रॉबिन वेब कहती हैं, \"रिसोट्टो में क्विनोआ आम अनाज नहीं है, लेकिन प्रोटीन से भरपूर यह छोटा अनाज जल्दी पक जाता है और इससे रिसोट्टो जैसा बेहद खुशबूदार व्यंजन बनता है।\"",
"4","3/4 कप",
["1 1/2 बड़े चम्मच ऑलिव ऑयल (बाँटकर उपयोग करें)","1 मध्यम प्याज़ (बारीक कटा हुआ)","1 कप क्विनोआ","4 कप ऑर्गेनिक सब्ज़ी का स्टॉक (बिना नमक मिलाए, बाँटकर उपयोग करें)","4 कली लहसुन (बारीक कटी हुई)","7 पत्तियाँ केल (डंठल निकाले और पट्टियों में कटी हुई)","10 औंस सैल्मन (उबालकर टुकड़े किया हुआ)","1/8 छोटा चम्मच नमक","1/8 छोटा चम्मच काली मिर्च"],
["सैल्मन को उबालने के लिए: 4 क्वार्ट के सॉसपैन में पानी भरें और सैल्मन का फ़िले पानी में रखें। सॉसपैन को तेज़ आँच पर पानी के उबलने तक रखें। पानी उबलने पर पैन को आँच से उतार लें और 10 मिनट रखा रहने दें। मछली को पानी से निकालें और टुकड़े कर लें। एक तरफ़ रख दें।","4 क्वार्ट के सॉसपैन में मध्यम-तेज़ आँच पर 1 बड़ा चम्मच ऑलिव ऑयल गरम करें। जब तेल में लहरें दिखने लगें, तो कटा हुआ प्याज़ डालें। प्याज़ को पारदर्शी होने तक भूनें। प्याज़ के मिश्रण में क्विनोआ डालें और भूनने के लिए 2 मिनट चलाएँ।","क्विनोआ और प्याज़ में 1 कप सब्ज़ी का स्टॉक डालें। स्टॉक सोखे जाने तक चलाएँ। स्टॉक सोख लेने पर 1 कप और स्टॉक डालें। स्टॉक सोखे जाने तक चलाते रहें। बचा हुआ स्टॉक 1/2-कप की मात्रा में डालते जाएँ, हर बार उसके सोखे जाने तक चलाएँ। आँच से उतार लें।","प्याज़-क्विनोआ का मिश्रण तैयार करते समय, एक सॉते पैन में मध्यम-तेज़ आँच पर 1/2 बड़ा चम्मच तेल कटे हुए लहसुन के साथ गरम करें। जब लहसुन चटकने लगे, तो पैन में कटी हुई केल डालें। केल को तेल और लहसुन में लपेटने के लिए पलटें। केल के मिश्रण को खुशबू आने तक, लगभग 2 मिनट पलटते रहें। केल के मिश्रण को आँच से उतार लें।","क्विनोआ तैयार हो जाने पर केल और सैल्मन डालें। मिलाने के लिए चलाएँ और स्वादानुसार नमक और काली मिर्च डालें।"],[]),
]
